-- INSERT TRANSACCIONAL CUOTAS MODERADORAS
INSERT INTO [RamedicasBI].[dbo].[rmd_tracm_web]
SELECT 
F.FacSec AS 'facsec',
K.KarSec AS 'karsec',
F.facfec AS 'facfec',
F.FacfecDes AS 'facfecdes',
F.FacNitSec AS 'facnitsec',
F.FacCliSec AS 'facclisec',
F.FacVenCod AS 'facvencod',
F.FacTipCod AS 'factipcod',
F.FacNro AS 'facnro',
F.FacEst AS 'facest',
F.FacAutEstado AS 'facautest',
K.KarEst AS 'karest',
K.KarNat AS 'karnat',
K.ArtSec AS 'artsec',
K.PreArtCod AS 'preart',
K.KarArtEmb AS 'emb',
CASE 
    WHEN K.KarNat = '-' THEN CAST((K.KarUni * -1) AS INT)
    ELSE CAST(K.KarUni AS INT) END AS 'und',
K.KarPre AS 'preund',
K.KarArtIva AS 'iva',
CASE
    WHEN K.KarNat = '-' THEN (K.karvaltotMenDes *-1)
    ELSE K.karvaltotMenDes END AS 'vlrtotbrt',
CASE 
    WHEN K.KarNat = '-' THEN ((K.karvaltotMenDes + K.KarArtIva) * -1)
    ELSE (K.karvaltotMenDes + K.KarArtIva) END AS 'vlrtotnto',
F.BodSucCCSec AS 'bodsuccsec',
F.FacEscPac AS 'facescpac',
F.FacSecDev AS 'facsecdev',
F.FacDocCom AS 'facdoccom',
F.FacUsuCod AS 'facusucre',
F.FacUsuMod AS 'facusumod',
F.FacFecHorMod AS 'facfecmod',
F.FacUsuAnu AS 'facanuusu',
F.FacFecAnu AS 'facfecanu',
F.FacAnuObs AS 'facobsanu',
F.FacObs AS 'facobs'
FROM [Ramedicas].[dbo].[factura] F
INNER JOIN [Ramedicas].[dbo].[Kardex] K ON F.FacSec = K.FacSec
WHERE FacTipCod IN ('CMA', 'CMB', 'CMC', 'CMD', 'CME', 'CMF', 'CMG', 'CMH', 'CMI', 'CMJ', 'CMK', 
'CML', 'CMM', 'CMN', 'CMO', 'CMP', 'CMQ', 'CMR', 'CMS', 'CMT', 'CMU', 'CMV', 'CMX', 'CMY') AND F.FacSecDev in ('22066718', '22066809', '22066910', '22067682', '22068270', '22072299', '22072580', '22072814', '22072853', '22073067', '22073632', '22073922', '22074053', '22074085', '22074175', '22074925', '22076026', '22076660', '22076875', '22077829', '22078358', '22078907', '22078997', '22079056', '22079298', '22080046', '22082521', '22084715', '22084953', '22085025', '22085374', '22085478', '22085644', '22085805', '22085861', '22085918', '22086008', '22086204', '22086411', '22094402', '22094457', '22094658', '22094712', '22094856', '22095881', '22096025', '22096437', '22096508', '22096695', '22096813', '22097137', '22097724', '22098024', '22098227', '22101487', '22102635', '22102917', '22103220', '22103258', '22104346', '22109483', '22109527', '22109876', '22110923', '22112269', '22112714', '22113307', '22116231', '22116418', '22116556', '22116726', '22116947', '22117170', '22117343', '22117673', '22117898', '22117992', '22118289', '22118497', '22119001', '22119066', '22119127', '22119213', '22122516', '22123571', '22124131', '22124326', '22124514', '22125825', '22128208', '22128408', '22128871', '22128924', '22129668', '22129837', '22130290', '22130356', '22130581', '22130704', '22131006', '22135190', '22136202', '22136319', '22136452', '22137456', '22146956', '22147162', '22147211', '22147300', '22147358', '22147464', '22147827', '22147887', '22147924', '22148017', '22148163', '22148216', '22148439', '22148530', '22149247', '22149764', '22150049', '22150489', '22150562', '22151040', '22151080', '22153476', '22153531', '22153643', '22153797', '22154007', '22154129', '22154309', '22154383', '22154455', '22154521', '22154611', '22155379', '22155557', '22155645', '22160278', '22160439', '22160625', '22160719', '22160823', '22161083', '22161469', '22161569', '22162097', '22162727', '22162797', '22162850', '22163141', '22163470', '22163755', '22163805', '22163911', '2216